begin;
grant workspace_admin_owner,workspace_context_owner to current_user;
insert into public.election(id,year,round) values('50000000-0000-0000-0000-000000000001',2099,'generales');
insert into public.category(id,name) values('51000000-0000-0000-0000-000000000001','AUTHORIZED FACET TEST'),('51000000-0000-0000-0000-000000000002','PBA DISTRITO AS SECTION');
insert into public.jurisdiction(id,distrito_code,seccion_code,seccion_name,distrito_name,circuito_code,circuito_name,establecimiento_code,establecimiento_name,mesa_code) values
 ('52000000-0000-0000-0000-000000000001','02','027','Exact','Buenos Aires','00001','Circuit one','E1','School one',7),('52000000-0000-0000-0000-000000000002','02',null,null,null,null,null,null,null,null);
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) values
 ('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','seccion','A',1,'official','authorized-official',1),
 ('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','seccion','B',1,'fiscalizacion','unauthorized-fiscal',2),
 ('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000002','51000000-0000-0000-0000-000000000001','distrito','C',1,'official','unauthorized-coarse',3),
 ('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000002','distrito','D',1,'official','authorized-pba-distrito',4),
 ('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000002','distrito','E',2,'official','authorized-pba-dedup',5);
set local role workspace_admin_owner;
insert into workspace_private.organization(id,slug,display_name,entitlement_revision) values
 ('40000000-0000-0000-0000-000000000001','facets-one','Facets One',1),('40000000-0000-0000-0000-000000000002','facets-two','Facets Two',1);
insert into workspace_private.organization_membership(organization_id,user_id,membership_revision,revoked_at) values
 ('40000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000001',1,null),
 ('40000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000001',1,null),
 ('40000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000002',2,statement_timestamp());
insert into workspace_private.section_scope values('02','027'),('02','028');
insert into workspace_private.organization_section_entitlement(organization_id,distrito_code,seccion_code) values
 ('40000000-0000-0000-0000-000000000001','02','027'),('40000000-0000-0000-0000-000000000002','02','028');
reset role; set local role workspace_context_owner;
insert into workspace_private.workspace_context(session_id,user_id,organization_id,membership_revision,entitlement_revision,context_revision,fixed_expires_at,revoked_at) values
 ('42000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,1,1,statement_timestamp()+interval '1 hour',null),
 ('42000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000002',1,1,1,statement_timestamp()+interval '1 hour',null),
 ('42000000-0000-0000-0000-000000000003','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,0,1,statement_timestamp()+interval '1 hour',null),
 ('42000000-0000-0000-0000-000000000004','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,1,1,statement_timestamp()+interval '1 hour',statement_timestamp()),
 ('42000000-0000-0000-0000-000000000005','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,1,1,statement_timestamp()-interval '1 second',null),
 ('42000000-0000-0000-0000-000000000006','41000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001',2,1,1,statement_timestamp()+interval '1 hour',null),
 ('42000000-0000-0000-0000-000000000007','41000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,1,1,statement_timestamp()+interval '1 hour',null);
reset role;
select plan(25);
select ok((select strpos(definition,'trusted_workspace_claims')>0 and strpos(definition,'from workspace_private.workspace_context')>0 and strpos(definition,'trusted_workspace_claims')<strpos(definition,'from workspace_private.workspace_context') from (select pg_get_functiondef('workspace_private.authorized_section_scopes()'::regprocedure) definition) source),'trusted claims are captured before relation access');
select ok((select pg_get_functiondef('workspace_api.official_facets(uuid,uuid,text,text,text,text)'::regprocedure) like '%source_kind=''official''%' and pg_get_functiondef('workspace_api.official_facets(uuid,uuid,text,text,text,text)'::regprocedure) like '%j.seccion_code is not null%' and pg_get_functiondef('workspace_api.official_facets(uuid,uuid,text,text,text,text)'::regprocedure) not like '%fiscalizacion%'),'facets use only exact official source rows without a raw fallback');
select ok(not has_function_privilege('anon','workspace_api.official_facets(uuid,uuid,text,text,text,text)','EXECUTE') and not has_function_privilege('service_role','workspace_api.official_facets(uuid,uuid,text,text,text,text)','EXECUTE') and has_function_privilege('authenticated','workspace_api.official_facets(uuid,uuid,text,text,text,text)','EXECUTE'),'only authenticated reaches the official facets interface');
select ok(to_regclass('public.result_row_authorized_official_facets_idx') is not null and to_regclass('workspace_private.organization_section_entitlement_active_scope_idx') is not null,'official and entitlement indexes cover bounded discovery');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','ok','active context is authorized');
select is((workspace_api.official_facets()->>'total')::bigint,2::bigint,'official exact rows include normalized PBA distrito sections but exclude fiscalizacion and coarse province rows');
select is(workspace_api.official_facets()->'exclusions','[{"reason":"non_official_source_rows","rows":1}]'::jsonb,'no-selector continuity reports bounded source exclusions without leaking ambiguous coarse rows');
select ok(not (workspace_api.official_facets()->'truncated')::boolean and jsonb_array_length(workspace_api.official_facets()->'facets')=2,'authorized payload is bounded and complete');
select is(workspace_api.official_facets()->'facets'->0->>'distrito_name','Buenos Aires','district name stays on an authorized exact tuple');
select is(workspace_api.official_facets()->'facets'->0->>'seccion_name','Exact','section name stays on an authorized exact tuple');
select ok(not exists(select 1 from jsonb_array_elements(workspace_api.official_facets()->'facets') f where f->>'distrito_code' is distinct from '02' or f->>'seccion_code' is distinct from '027'),'name metadata does not widen exact-section membership');
select is(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','02','027','00001','E1')->'mesas','[{"election_id":"50000000-0000-0000-0000-000000000001","category_id":"51000000-0000-0000-0000-000000000001","distrito_code":"02","seccion_code":"027","circuito_code":"00001","establecimiento_code":"E1","mesa_code":7}]'::jsonb,'authorized selectors expose only the exact official mesa lineage');
reset role; set local role workspace_admin_owner; insert into workspace_private.organization_section_entitlement(organization_id,distrito_code,seccion_code) values('40000000-0000-0000-0000-000000000001','02','028'); reset role;
insert into public.jurisdiction(id,distrito_code,seccion_code,seccion_name,distrito_name) values('52000000-0000-0000-0000-000000000003','02','028',null,'Other district');
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) values('50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000003','51000000-0000-0000-0000-000000000001','seccion','F',1,'official','authorized-canonical-metadata',6);
set local role authenticated; select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select ok(jsonb_array_length(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001')->'facets')=2 and not exists(select 1 from jsonb_array_elements(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001')->'facets') f where f->>'distrito_name_status' is distinct from 'conflict' or (f->>'distrito_name_variant_count')::integer is distinct from 2 or f->'distrito_name' is distinct from 'null'::jsonb),'district metadata is canonical across both authorized sections with an exact conflict count');
select is((select case when count(*)=2 and count(distinct f->>'seccion_code')=2 then jsonb_object_agg(f->>'seccion_code',jsonb_build_object('status',f->>'seccion_name_status','count',(f->>'seccion_name_variant_count')::integer)) end from jsonb_array_elements(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001')->'facets') f),'{"027":{"status":"present","count":1},"028":{"status":"missing","count":0}}'::jsonb,'section metadata remains canonical on two distinct authorized section tuples');
select is(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','02','027')->'facets'->0->'distrito_name_status','"conflict"'::jsonb,'a selected section retains district metadata canonicalized across authorized sections');
reset role; delete from public.result_row where archive_entry_id='authorized-canonical-metadata'; delete from public.jurisdiction where id='52000000-0000-0000-0000-000000000003'; set local role workspace_admin_owner; delete from workspace_private.organization_section_entitlement where organization_id='40000000-0000-0000-0000-000000000001' and distrito_code='02' and seccion_code='028'; reset role;
insert into public.category select gen_random_uuid(),'AUTHORIZED FACET OVERFLOW '||g from generate_series(1,199) g;
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '50000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001',id,'seccion','Z',1,'official','authorized-overflow',row_number() over() from public.category where name like 'AUTHORIZED FACET OVERFLOW %';
set local role authenticated; select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets(),jsonb_build_object('status','payload_too_large','facets','[]'::jsonb,'total',201,'truncated',true,'circuitos','[]'::jsonb,'establecimientos','[]'::jsonb,'mesas','[]'::jsonb,'exclusions',jsonb_build_array(jsonb_build_object('reason','coarse_facets_overflow','rows',201))),'coarse overflow fails closed and reports the greatest relevant total');
reset role; with inserted as (insert into public.jurisdiction(distrito_code,seccion_code,seccion_name,distrito_name,circuito_code) select '02','027','Exact','Buenos Aires','C'||lpad(g::text,5,'0') from generate_series(1,200) g returning id,circuito_code) insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '50000000-0000-0000-0000-000000000001',id,'51000000-0000-0000-0000-000000000001','circuito',circuito_code,1,'official','authorized-circuit-overflow',row_number() over(order by circuito_code) from inserted; set local role authenticated; select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true); select is(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','02','027'),jsonb_build_object('status','payload_too_large','facets','[]'::jsonb,'total',201,'truncated',true,'circuitos','[]'::jsonb,'establecimientos','[]'::jsonb,'mesas','[]'::jsonb,'exclusions',jsonb_build_array(jsonb_build_object('reason','circuitos_overflow','rows',201))),'circuit overflow fails closed with depth-specific evidence');
reset role; with inserted as (insert into public.jurisdiction(distrito_code,seccion_code,seccion_name,distrito_name,circuito_code,establecimiento_code) select '02','027','Exact','Buenos Aires','00001','X'||lpad(g::text,5,'0') from generate_series(1,200) g returning id,establecimiento_code) insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '50000000-0000-0000-0000-000000000001',id,'51000000-0000-0000-0000-000000000001','establecimiento',establecimiento_code,1,'official','authorized-establishment-overflow',row_number() over(order by establecimiento_code) from inserted; set local role authenticated; select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true); select is(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','02','027','00001'),jsonb_build_object('status','payload_too_large','facets','[]'::jsonb,'total',201,'truncated',true,'circuitos','[]'::jsonb,'establecimientos','[]'::jsonb,'mesas','[]'::jsonb,'exclusions',jsonb_build_array(jsonb_build_object('reason','circuitos_overflow','rows',201),jsonb_build_object('reason','establecimientos_overflow','rows',201))),'establishment overflow reports every overflowing relevant depth');
reset role; with inserted as (insert into public.jurisdiction(distrito_code,seccion_code,seccion_name,distrito_name,circuito_code,establecimiento_code,mesa_code) select '02','027','Exact','Buenos Aires','00001','E1',1000+g from generate_series(1,200) g returning id,mesa_code) insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '50000000-0000-0000-0000-000000000001',id,'51000000-0000-0000-0000-000000000001','mesa',mesa_code::text,1,'official','authorized-mesa-overflow',row_number() over(order by mesa_code) from inserted; set local role authenticated; select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000001','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true); select is(workspace_api.official_facets('50000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','02','027','00001','E1'),jsonb_build_object('status','payload_too_large','facets','[]'::jsonb,'total',201,'truncated',true,'circuitos','[]'::jsonb,'establecimientos','[]'::jsonb,'mesas','[]'::jsonb,'exclusions',jsonb_build_array(jsonb_build_object('reason','circuitos_overflow','rows',201),jsonb_build_object('reason','establecimientos_overflow','rows',201),jsonb_build_object('reason','mesas_overflow','rows',201))),'mesa overflow reports every overflowing relevant depth with empty payload arrays');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000002','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets(),jsonb_build_object('status','ok','facets','[]'::jsonb,'total',0,'truncated',false,'circuitos','[]'::jsonb,'establecimientos','[]'::jsonb,'mesas','[]'::jsonb,'exclusions','[]'::jsonb),'a second organization can be authorized with an empty result');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000003','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','context_stale','stale entitlement revision is denied distinctly');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000004','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','context_revoked','revoked session context is denied distinctly');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000001','session_id','42000000-0000-0000-0000-000000000005','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','context_expired','expired fixed context is denied distinctly');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000002','session_id','42000000-0000-0000-0000-000000000006','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','membership_revoked','revoked membership is denied distinctly');
select set_config('request.jwt.claims',jsonb_build_object('sub','41000000-0000-0000-0000-000000000002','session_id','42000000-0000-0000-0000-000000000007','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_facets()->>'status','claims_mismatch','session user mismatch is denied distinctly');
select * from finish();
rollback;
